pug:
table.row.brad-full.white-bg
    tr
        td.wrapper.last.offset-by-one
            table.ten.columns
                tr
                    td.text-pad-small.pb40.pt44.bb
                        p.middle-title.pb32 {{ text_1 }}
                        a(href="#" universal="true" target="_blank")
                            img.center(src="{{ image_1 }}")
                        ul.pt32
                            li.text.pb8 {{ text_2 }}
                            li.text.pb8 {{ text_3 }}
                            li.text {{ text_4 }}
                tr
                    td.text-pad-small.pb44.pt40
                        a(href="#" universal="true" target="_blank")
                            img.center(src="{{ image_2 }}")
                        ul.pt32
                            li.text.pb8 {{ text_5 }}
                            li.text {{ text_6 }}

styl:
.brad-full { border-radius: 32px !important; }
.bb { border-bottom: 1px solid #d9d9db; }
.white-bg { background-color: #fff; }
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb8 { padding-bottom: 8px; }
.pb32 { padding-bottom: 32px; }
.pb44 { padding-bottom: 44px; }
.pt32 { padding-top: 32px; }
.pt44 { padding-top: 44px; }
